1	/**
2	 * A map drawing itself, in a real browser, against a real server, **with no
3	 * model key at all**.
4	 *
5	 * It is the one thing no component test can claim: that a reviewer who has
6	 * configured nothing can open the first screen, press a card, and watch a map
7	 * build itself claim by claim — with a reserved rectangle standing where the next
8	 * claim will go, every proposal the rules refused on screen in the validator's
9	 * own words, and a receipt at the end saying what it cost.
10	 *
11	 * **It plays a recording, through the same route, the same eight events and the
12	 * same canvas a live run uses.** The only substitution anywhere is where the
13	 * bytes came from, which is what makes this evidence about the live route rather
14	 * than about a second one.
15	 *
16	 * **It skips itself when there is nothing recorded**, in one line saying so. The
17	 * recordings are made against a real key by the person who holds it; until one is
18	 * committed under `backend/recordings/`, this test has nothing to play and says
19	 * that rather than failing. The moment one lands it runs, with no change here.
20	 *
21	 * **Nothing below reads a value the screen has not settled on.** The waiting is
22	 * `waiting.ts`'s, the same helpers the stored example's test uses: a named signal
23	 * every time, never a sleep, and never `innerText` — which is empty until the
24	 * drawing library has measured a tile, and which is how a chip that plainly read
25	 * `.19` was once read as nothing at all.
26	 *
27	 * **A growing map needs one signal the stored one does not**, and it is the
28	 * reason this file has helpers of its own: on a stored map everything arrives at
29	 * once, and here the screen is *correct* and *incomplete* at the same moment for
30	 * minutes at a time. So every read below waits for the count it is about — this
31	 * many claims, this many rectangles, the receipt — rather than for the page.
32	 *
33	 * Nothing here is a number typed into this file. Every figure is read off the
34	 * screen and compared with itself across a change, or checked for its shape.
35	 */
36	
37	import { expect, type Page, test } from "@playwright/test";
38	import { whereTheMapCameToRest, whereTheTileSits } from "./waiting.js";
39	
40	/** The sentence the first screen's first card carries, as a reader would type it. */
41	const THE_SENTENCE = "The Strait of Hormuz is going to open next week.";
42	
43	/**
44	 * How long a whole run is allowed to take before this test gives up on it.
45	 *
46	 * **A replay takes as long as its recording**, because the pacing is the
47	 * server's and the number of events is the file's — a twenty-proposal run is
48	 * four times the twenty seconds a five-proposal one takes, and neither number
49	 * is this test's to know. So the bound below is not a measurement and is not
50	 * tuned to a machine: it is generous on purpose, and exists only so that a run
51	 * which has genuinely stopped fails as a test rather than hanging.
52	 *
53	 * The default fifteen seconds is the wrong bound for exactly one thing in this
54	 * file — waiting for a run to finish — and the right one everywhere else, so it
55	 * is named here and used there.
56	 */
57	const A_WHOLE_RUN = 120_000;
58	
59	// Every test here plays a recording from beginning to end, so each needs room
60	// for one. It is set on the file rather than in the configuration because it is
61	// a fact about these tests: the stored example's tests next door are right to
62	// be held to a minute.
63	test.describe.configure({ timeout: A_WHOLE_RUN + 60_000 });
64	
65	/**
66	 * What this copy of the server says it can play back without a key.
67	 *
68	 * Asked of the server rather than read off the screen: whether this test has
69	 * anything to do at all is a fact about the server, and reading it off the page
70	 * would make the skip depend on the very screen being tested.
71	 */
72	async function whatCanBeReplayed(page: Page): Promise<{ example: string }[]> {
73	  const answer = await page.request.get("/api/readyz");
74	  const said = (await answer.json()) as { replayable?: { example: string }[] };
75	  return said.replayable ?? [];
76	}
77	
78	/** What watching a whole run saw. */
79	interface WhatItSaw {
80	  /** True when, at some moment, a rectangle stood and not one claim had arrived. */
81	  readonly rectangleBeforeAnyClaim: boolean;
82	  /**
83	   * The words on the first rectangle, read at a moment when no claim had
84	   * arrived — so it is the one held open for the reader's own sentence and not
85	   * one of the frontier's, which carry *one step on from "…"*.
86	   *
87	   * Empty when no such moment was seen.
88	   */
89	  readonly firstRectangleSaid: string;
90	  /** The most rectangles that stood at once. */
91	  readonly mostRectangles: number;
92	  /**
93	   * True when, at some moment, two boxes on the map stood in the same place.
94	   *
95	   * The place they would share is the map's origin, where the hypothesis is:
96	   * a box the layout has not placed yet used to be drawn there, so every
97	   * arriving claim sat on top of the first one until the layout answered.
98	   */
99	  readonly everStacked: boolean;
100	  /**
101	   * How many rectangles stood at the moment each claim arrived, in order.
102	   *
103	   * The growing edge saying where the map is going, step by step, rather than
104	   * only at the start. **The last entry is allowed to be none**: the frontier
105	   * empties when the last claim closes, and no rectangle may stand where
106	   * nothing is coming.
107	   */
108	  readonly heldWhenEachClaimArrived: readonly number[];
109	  /**
110	   * How many claims were on the map, every time that number changed.
111	   *
112	   * The sequence rather than the largest of them: the largest is whatever the
113	   * map ended up with, which is a fact about the end and says nothing at all
114	   * about how the map got there. A map that appeared all at once and a map that
115	   * grew claim by claim have the same largest number and completely different
116	   * sequences.
117	   */
118	  readonly claimsWentOn: readonly number[];
119	  /**
120	   * How many claims were on the map the first time any likelihood appeared, and
121	   * how many appeared at that moment.
122	   *
123	   * Both are zero when none ever did. Together they are the statement that the
124	   * chips resolve **last** and **once**: the first number arrives when the map
125	   * is complete, and every other number arrives in the same breath.
126	   */
127	  readonly whenTheNumbersCame: { readonly claims: number; readonly numbers: number };
128	}
129	
130	/** Where the page keeps what it has seen of itself. */
131	declare global {
132	  interface Window {
133	    theRecord?: WhatItSaw & { rectangleBeforeAnyClaim: boolean };
134	    stopWatching?: () => void;
135	  }
136	}
137	
138	/**
139	 * Have the page start watching itself, before anything is asked for.
140	 *
141	 * **Four of the things this test is for are about a screen that is moving**, and
142	 * a moving screen cannot be checked by looking at it once: *a rectangle is drawn
143	 * before any claim*, *rectangles stand at the growing edge*, *the claims arrive
144	 * one at a time* and *not one likelihood is on screen until the map is finished*
145	 * are each true at some moments and false at others, and by the time an
146	 * assertion has been written the moment it was about is gone. Polling for one of
147	 * them races the run; asserting after it is over asserts about the wrong moment.
148	 *
149	 * So the page watches itself. Every change to the page is looked at — which is
150	 * every moment the screen was different — and what was on it is written down.
151	 * Nothing here sleeps, and nothing here can miss a moment that a poll would have
152	 * stepped over.
153	 *
154	 * **It is installed before the press**, and awaited, so that the very first
155	 * frame of the run is inside the record. Starting it after the press leaves the
156	 * one moment the first assertion is about — a rectangle standing with no claim
157	 * beside it — outside the window being watched, on a fast replay.
158	 *
159	 * @param page The page the map will be on.
160	 */
161	async function startWatching(page: Page): Promise<void> {
162	  await page.evaluate(() => {
163	    const record = {
164	      rectangleBeforeAnyClaim: false,
165	      firstRectangleSaid: "",
166	      mostRectangles: 0,
167	      everStacked: false,
168	      heldWhenEachClaimArrived: [] as number[],
169	      claimsWentOn: [] as number[],
170	      whenTheNumbersCame: { claims: 0, numbers: 0 },
171	    };
172	    window.theRecord = record;
173	
174	    const look = (): void => {
175	      const held = document.querySelectorAll(".skeleton-tile").length;
176	      const claims = document.querySelectorAll(".tile").length;
177	      // A chip says on its own face whether it is showing a number or words,
178	      // and that is the marker to count: every chip renders a reading, and on
179	      // a growing map most of them are reading an absence out.
180	      const numbers = document.querySelectorAll('.belief-chip[data-reading="number"]').length;
181	
182	      if (held > 0 && claims === 0) {
183	        record.rectangleBeforeAnyClaim = true;
184	        // **Read here, and never again from the live page.** What the first
185	        // rectangle says is true of one moment: the moment after it is drawn
186	        // and before the first claim replaces it with the frontier's. Reading
187	        // it in a second round trip asks a screen that has moved on — and on a
188	        // cold machine the whole run can finish in between, so the rectangle is
189	        // not merely different, it is gone.
190	        record.firstRectangleSaid = document.querySelector(".skeleton-tile")?.textContent ?? "";
191	      }
192	      record.mostRectangles = Math.max(record.mostRectangles, held);
193	      if (record.claimsWentOn[record.claimsWentOn.length - 1] !== claims) {
194	        // What the growing edge was saying at the moment this claim arrived.
195	        if (claims > 0) {
196	          record.heldWhenEachClaimArrived.push(held);
197	        }
198	        record.claimsWentOn.push(claims);
199	      }
200	      // Two boxes in one place. The place they would share is the map's origin,
201	      // where a box the layout has not placed yet used to be drawn.
202	      const places = [...document.querySelectorAll(".react-flow__node")].map(
203	        (one) => (one as HTMLElement).style.transform,
204	      );
205	      if (new Set(places).size !== places.length) {
206	        record.everStacked = true;
207	      }
208	      if (numbers > 0 && record.whenTheNumbersCame.numbers === 0) {
209	        record.whenTheNumbersCame = { claims, numbers };
210	      }
211	    };
212	
213	    const watching = new MutationObserver(look);
214	    window.stopWatching = () => watching.disconnect();
215	    watching.observe(document.body, { subtree: true, childList: true, attributes: true });
216	    look();
217	  });
218	}
219	
220	/**
221	 * Stop watching, and read back what the page saw of itself.
222	 *
223	 * **It waits for nothing.** The waiting is done by the named signals above it,
224	 * which is where a test that has to give up belongs: a watcher that settled on a
225	 * signal of its own would hang until the whole test timed out on a run that
226	 * broke, and the failure a reader saw would be *"test timed out"* rather than
227	 * *"the run said it failed"*.
228	 *
229	 * @param page The page the map is on.
230	 */
231	async function whatItSaw(page: Page): Promise<WhatItSaw> {
232	  return await page.evaluate(() => {
233	    window.stopWatching?.();
234	    return window.theRecord as WhatItSaw;
235	  });
236	}
237	
238	/**
239	 * Wait until the run is over, which is the receipt arriving and the map saying
240	 * why it stopped.
241	 *
242	 * Two signals rather than one, because they are two events: the receipt is what
243	 * the run cost and the closing line is why it ended, and a screen that had the
244	 * first and not the second would be read here as finished when it is not.
245	 *
246	 * **This is the one wait in this file with a bound of its own**, and it is the
247	 * one that needs one: everything else here is waiting for the page to catch up
248	 * with something that has already happened, where fifteen seconds is generous.
249	 * This waits for a whole recording to play, which takes as long as the
250	 * recording is — see `A_WHOLE_RUN`.
251	 */
252	async function waitUntilItStops(page: Page): Promise<void> {
253	  await expect(page.locator(".receipt-strip")).toBeVisible({ timeout: A_WHOLE_RUN });
254	  await expect(page.locator(".done-line")).toBeVisible({ timeout: A_WHOLE_RUN });
255	  // Every rectangle goes when the likelihoods land: the set of claims still open
256	  // is empty by definition once the map is finished.
257	  await expect(page.locator(".skeleton-tile")).toHaveCount(0);
258	}
259	
260	/** Every pair of boxes on the map that overlap. Empty is the only right answer. */
261	async function boxesRunningIntoEachOther(page: Page): Promise<string[]> {
262	  return await page.locator(".react-flow__node").evaluateAll((boxes) => {
263	    const seen = boxes.map((box) => ({
264	      id: (box as HTMLElement).dataset.id ?? "?",
265	      at: box.getBoundingClientRect(),
266	    }));
267	    const found: string[] = [];
268	    for (let one = 0; one < seen.length; one += 1) {
269	      for (let other = one + 1; other < seen.length; other += 1) {
270	        const a = seen[one];
271	        const b = seen[other];
272	        if (
273	          a !== undefined &&
274	          b !== undefined &&
275	          a.at.left < b.at.right &&
276	          b.at.left < a.at.right &&
277	          a.at.top < b.at.bottom &&
278	          b.at.top < a.at.bottom
279	        ) {
280	          found.push(`${a.id} runs into ${b.id}`);
281	        }
282	      }
283	    }
284	    return found;
285	  });
286	}
287	
288	test("a map draws itself from a recording, with no model key", async ({ page }) => {
289	  await page.goto("/");
290	
291	  const replayable = await whatCanBeReplayed(page);
292	  test.skip(
293	    replayable.length === 0,
294	    "This server has no committed recording to play, so there is no generation to watch.",
295	  );
296	
297	  // The first screen says what this copy is, and says only what is true. Record
298	  // 0012's sentence — *these four run from recordings made on <day>* — is
299	  // printed word for word when all four can be played and all four were made on
300	  // one day; anything else says how many there really are, in the same voice.
301	  // Either way it names a day from the server's own readiness answer, and either
302	  // way the field for a sentence of your own is disabled with it, because a
303	  // field that takes typing and then does nothing reads as a broken tool.
304	  const keyless = page.locator(".launchpad__keyless").first();
305	  await expect(keyless).toBeVisible();
306	  await expect(keyless).toHaveText(/^No model key configured — .*\d{4}-\d{2}-\d{2}/);
307	  const said = ((await keyless.textContent()) ?? "").trim();
308	  expect(said.includes("these four run from recordings")).toBe(replayable.length === 4);
309	  await expect(page.getByLabel("An event you think will happen")).toBeDisabled();
310	
311	  // From here the page watches itself, because what follows is a screen that is
312	  // moving and four of the claims made about it are about moments, not about the
313	  // end. It starts **before** the press, so the very first frame is inside the
314	  // record; it is read at the bottom of this test.
315	  await startWatching(page);
316	
317	  // The card that has a recording. It sends its sentence, exactly as a reader
318	  // would type it — the same request a live run sends — and it is opened with
319	  // the keyboard, because every way into this product is usable without a mouse.
320	  const card = page.getByRole("button", { name: new RegExp(THE_SENTENCE) });
321	  await card.focus();
322	  await expect(card).toBeFocused();
323	  await page.keyboard.press("Enter");
324	
325	  // **The first paint is a reserved rectangle, not a spinner.** That it appeared
326	  // at all is asked of the live page; **what it said is read off the record the
327	  // page kept of itself**, at the bottom of this test, because the words on the
328	  // first rectangle are true of exactly one moment — after it is drawn and
329	  // before the first claim replaces it with the frontier's.
330	  await expect(page.locator(".skeleton-tile").first()).toBeVisible();
331	
332	  // The badge says this session is a replay, from the first frame, before the
333	  // receipt that also says so has arrived — and it is beside the map's name
334	  // rather than over the map, because nothing in this product sits over the map.
335	  await expect(page.locator(".map-bar .replay-badge")).toBeVisible();
336	  await expect(page.locator(".canvas .replay-badge")).toHaveCount(0);
337	
338	  // Nothing spins anywhere, at any point.
339	  await expect(page.getByRole("progressbar")).toHaveCount(0);
340	
341	  // The map grows, and the first claim to arrive reads an absence where its
342	  // likelihood will go.
343	  await expect(page.locator(".tile").first()).toBeVisible();
344	
345	  // Where the first tile came to rest, before any of the others arrive. Nothing
346	  // already placed may move, and this is what that promise is checked against.
347	  const firstTile = page.locator(".react-flow__node.react-flow__node-claim").first();
348	  const wasAt = await whereTheTileSits(firstTile);
349	
350	  // Every proposal the rules refused is on screen, in the validator's own words
351	  // — and a run that refused nothing says that, rather than leaving an empty
352	  // space a reader has to interpret. Which of the two this recording shows is
353	  // the recording's business: **a recording need not contain a refusal** (Kent,
354	  // 2026-09-20), and what is checked here is that the strip is never silent.
355	  await waitUntilItStops(page);
356	  const strip = page.locator(".refusal-strip");
357	  await expect(strip).toBeVisible();
358	  const refusals = await page.locator(".refusal-strip__row").count();
359	  if (refusals > 0) {
360	    await expect(page.locator(".refusal-strip__reason").first()).not.toBeEmpty();
361	  } else {
362	    await expect(strip).toContainText("The rules refused nothing in this run.");
363	  }
364	  // The rule's stable code is carried on the event and drawn nowhere.
365	  await expect(strip).not.toContainText("cycle");
366	
367	  // The receipt: ten labelled readings, every one a field, none of them derived.
368	  const receipt = page.locator(".receipt-strip").first();
369	  await expect(receipt.locator(".receipt-strip__label")).toHaveText([
370	    "model",
371	    "calls",
372	    "tokens in",
373	    "tokens out",
374	    "read from cache",
375	    "web searches",
376	    "cost",
377	    // A replay's clock is the replay's, and the row says so: a few seconds of
378	    // paced playback beside a map that took eleven minutes to make.
379	    "the replay took",
380	    "how hard the model tried",
381	    "mode",
382	  ]);
383	  // How hard the model tried is a plain word, the one the service takes. Two
384	  // maps of the same sentence at the same seed can differ because of it alone,
385	  // so it is a reading rather than a footnote.
386	  await expect(receipt.locator('[data-field="effort"] .receipt-strip__reading')).toHaveText(
387	    /^(default|low|medium|high|xhigh|max)$/,
388	  );
389	  // A replay calls nothing and spends nothing, and that zero is printed rather
390	  // than hidden — as money, which has two places, and as an exact zero rather
391	  // than as the bound a run that spent less than a penny would print.
392	  await expect(receipt.locator('[data-field="mode"] .receipt-strip__reading')).toContainText(
393	    "replay",
394	  );
395	  await expect(receipt.locator('[data-field="dollars"] .receipt-strip__reading')).toHaveText(
396	    "$0.00",
397	  );
398	
399	  // The likelihoods land once, at the end, all together: every claim on the map
400	  // now reads a number at two significant figures with its range, and none of
401	  // them reads an absence any more.
402	  const claims = await page.locator(".tile").count();
403	  await expect(page.locator('.belief-chip[data-owner="model"][data-reading="number"]')).toHaveCount(
404	    claims,
405	  );
406	  await expect(page.locator(".tile").first()).not.toContainText("no engine yet");
407	
408	  // The map is framed once more when it stops — the one moment nothing on it is
409	  // moving — and then it stays still.
410	  const atRest = await whereTheMapCameToRest(page);
411	  expect(atRest).not.toBe("");
412	
413	  // And the tile that was placed first is exactly where it was.
414	  expect(await whereTheTileSits(firstTile)).toBe(wasAt);
415	
416	  // No two boxes on the map overlap. A claim drawn on top of another is the one
417	  // failure a growing map makes that a finished one never does.
418	  expect(await boxesRunningIntoEachOther(page)).toEqual([]);
419	
420	  // And not one claim's or arrow's identifier reached the map or the panel
421	  // beside it. On a generated map they are twenty-six characters of the engine's
422	  // own bookkeeping, and a reader learns nothing from one.
423	  //
424	  // **The run's own name is the exception, and it is deliberate.** The line under
425	  // the map exists so that somebody can ask for this answer again — the map, the
426	  // seed, and the working — and the working is asked for by the generation's
427	  // name. It is printed once, there, beside the seed, and nowhere else.
428	  const onTheMap = (await page.locator(".map-body").textContent()) ?? "";
429	  expect(onTheMap).not.toMatch(/\b01[0-9A-HJKMNP-TV-Z]{24}\b/);
430	
431	  // Why the run stopped, in the engine's words for that reason — **printed once**
432	  // and said once. The live region is still a live region and still reads the
433	  // whole line out; what it no longer does is print it, because the same sentence
434	  // in two of three stacked strips of prose is the foot of the screen repeating
435	  // itself.
436	  const why = page.locator(".done-line__why");
437	  await expect(why).toBeVisible();
438	  const stopped = ((await why.textContent()) ?? "").trim();
439	  expect(stopped).not.toBe("");
440	  await expect(page.locator(".map-live")).toHaveClass(/map-live--spoken/);
441	  const howOften = await page.evaluate((sentence) => {
442	    const times = (text: string): number => text.split(sentence).length - 1;
443	    const spoken = document.querySelector(".map-live")?.textContent ?? "";
444	    return times(document.body.textContent ?? "") - times(spoken);
445	  }, stopped);
446	  expect(howOften).toBe(1);
447	
448	  // The map says where it is cut. A ten-claim map framed so its tiles stay
449	  // readable does not fit the stage, and a map that is cut with nothing saying
450	  // so is read as a map that ends there — which for a causal map is the worst
451	  // thing it can be read as. The same two-pixel rule the panel beside it uses,
452	  // measured by the stage about itself.
453	  const stage = page.locator(".canvas");
454	  const edges = await stage.evaluate((it) => ({
455	    left: (it as HTMLElement).dataset.moreLeft,
456	    right: (it as HTMLElement).dataset.moreRight,
457	    above: (it as HTMLElement).dataset.moreAbove,
458	    below: (it as HTMLElement).dataset.moreBelow,
459	  }));
460	  // Every edge has an answer — never a missing attribute, which would draw
461	  // nothing and mean nothing.
462	  expect(Object.values(edges).every((one) => one === "yes" || one === "no")).toBe(true);
463	  // And what it says is true of where the tiles actually are, checked against
464	  // the page rather than against a number written here.
465	  const really = await page.evaluate(() => {
466	    const room = document.querySelector(".canvas")?.getBoundingClientRect();
467	    const boxes = [...document.querySelectorAll(".react-flow__node")].map((one) =>
468	      one.getBoundingClientRect(),
469	    );
470	    if (room === undefined || boxes.length === 0) {
471	      return null;
472	    }
473	    return {
474	      left: boxes.some((at) => at.left < room.left - 1) ? "yes" : "no",
475	      right: boxes.some((at) => at.right > room.right + 1) ? "yes" : "no",
476	      above: boxes.some((at) => at.top < room.top - 1) ? "yes" : "no",
477	      below: boxes.some((at) => at.bottom > room.bottom + 1) ? "yes" : "no",
478	    };
479	  });
480	  expect(edges).toEqual(really);
481	
482	  // And what the screen did while it was moving, read off the record the page
483	  // kept of itself.
484	  const saw = await whatItSaw(page);
485	  // A rectangle stood before any claim had arrived: the first paint is the shape
486	  // of the thing being waited for, not a spinner — and it carried the reader's
487	  // own sentence, which is what makes it the shape of *this* wait rather than of
488	  // waiting in general.
489	  expect(saw.rectangleBeforeAnyClaim).toBe(true);
490	  expect(saw.firstRectangleSaid).toContain(THE_SENTENCE);
491	  // **Rectangles stood at the growing edge all the way through** — which is
492	  // what this now says, rather than "at some point there was one". A step with
493	  // no rectangle is a map that has stopped saying where it is going.
494	  //
495	  // The last claim is the exception and the only one: the frontier empties when
496	  // it closes, and no rectangle may stand where nothing is coming.
497	  //
498	  // **Continuous integration read a zero here, at the first claim, on 2026-09-21
499	  // and nowhere else.** The layout answers on a background thread, and on a
500	  // machine where its first answer lost the race to the first proposal the map
501	  // had no place for anything — so the claim was painted at the origin, where
502	  // the rectangle carrying the reader's own sentence had been, and the growing
503	  // edge went quiet. `frontend/src/graph/onTheGlass.ts` is the rule that is no
504	  // longer possible under, and `graph/__tests__/onTheGlass.test.ts` is the same
505	  // statement made without a browser.
506	  expect(saw.mostRectangles).toBeGreaterThan(0);
507	  expect(saw.heldWhenEachClaimArrived.length).toBe(claims);
508	  for (const [step, held] of saw.heldWhenEachClaimArrived.slice(0, -1).entries()) {
509	    expect(held, `no rectangle stood when claim ${step + 1} arrived`).toBeGreaterThan(0);
510	  }
511	  // **And no box was ever drawn in another box's place.** A box the layout has
512	  // not placed is not drawn at all — except the very first, which is a reserved
513	  // rectangle and never a claim: the origin is nobody's place before the layout
514	  // has answered anything, and the alternative is a first paint with nothing on
515	  // it. It used to be every box: each arriving claim sat on the hypothesis for
516	  // as long as the layout took to answer.
517	  expect(saw.everStacked).toBe(false);
518	  // **The claims arrived one at a time.** The count went 0, 1, 2, … and reached
519	  // the number on screen by rising by exactly one each time: a map that appeared
520	  // all at once would have gone 0 and then that number, and a map that redrew
521	  // itself would have gone down somewhere. Comparing the largest count with the
522	  // final count says nothing at all — they are the same number by definition.
523	  expect(saw.claimsWentOn[0]).toBe(0);
524	  expect(saw.claimsWentOn[saw.claimsWentOn.length - 1]).toBe(claims);
525	  expect(saw.claimsWentOn).toEqual(saw.claimsWentOn.map((_, step) => step));
526	  // **And the chips resolved last, and once.** The first likelihood to reach the
527	  // screen reached it when every claim was already on the map, and every other
528	  // likelihood reached it in the same breath — one event, one world, every
529	  // number. A chip that filled in as its causes arrived would have shown four
530	  // numbers nobody computed, three of them answers about a map that no longer
531	  // existed.
532	  expect(saw.whenTheNumbersCame.claims).toBe(claims);
533	  expect(saw.whenTheNumbersCame.numbers).toBe(claims);
534	
535	  // Nothing anywhere on this screen is a pop-up.
536	  await expect(page.getByRole("dialog")).toHaveCount(0);
537	});
