669	  // receipt and no refusal, so before this there was no way in at all — while
670	  // the screen had already fetched the one document that says how far it got.
671	  const read = page.getByRole("button", { name: /Read the working of this run/ });
672	  await expect(read).toBeVisible();
673	  await read.click();
674	  await expect(page.locator(".inspector__claim")).toHaveText("This generation");
675	
676	  // No box was ever drawn in another box's place while all that happened.
677	  expect(await boxesRunningIntoEachOther(page)).toEqual([]);
